#include "utils.h"
#include "../config.mcc/mcc_generated_files/timer/tca0.h"
#include <stdint.h>


volatile bool Frequency_05Hz = false;
volatile bool Frequency_1Hz = false;
volatile bool Frequency_2Hz = false;
volatile bool Frequency_4Hz = false;

volatile uint8_t Frequency_Counter = 0;

void TCA_OVF_Callback(void) {
  Frequency_4Hz = !Frequency_4Hz;

  Frequency_Counter++;
  if (Frequency_Counter >= 8) {
    Frequency_Counter = 0;
  }

  if (Frequency_Counter % 2 == 0) {
    Frequency_2Hz = !Frequency_2Hz;
  }

  if (Frequency_Counter % 4 == 0) {
    Frequency_1Hz = !Frequency_1Hz;
  }

  if (Frequency_Counter == 0) {
    Frequency_05Hz = !Frequency_05Hz;
  }
}

void Util_Init(void) {
  TCA0_OverflowCallbackRegister(TCA_OVF_Callback); // OVF 125ms
}